def longest_common_subsequence(a, b):
    """
    Calculates the longest subsequence common to the two input strings.

    Args:
        a (str): The first string to consider.
        b (str): The second string to consider.

    Returns:
        str: The longest string which is a subsequence of both strings. (If multiple subsequences of equal length exist, either is OK.)
    """
    if not a or not b:
        return ''

    elif a[0] == b[0]:
        return a[0] + longest_common_subsequence(a[1:], b[1:])

    else:
        return max(
            longest_common_subsequence(a, b[1:]),
            longest_common_subsequence(a[1:], b),
            key=len
        )

